fn unknown() -> HaError {
    HaError::OutcomeUnknown
}

fn check_deadline(deadline: Instant) -> Result<(), HaError> {
    if Instant::now() >= deadline {
        return Err(unknown());
    }
    Ok(())
}

fn require_blocking_worker() -> Result<(), HaError> {
    // Handle::block_on from an asynchronous runtime worker can panic or stall
    // the consensus tasks needed by follower ReadIndex. Fail before any I/O.
    if Handle::try_current().is_ok() {
        return Err(HaError::InvalidCluster);
    }
    Ok(())
}

pub(crate) fn native_v6_committed_fresh_ingress_read(
    &self,
    deadline: OriginalDeadline,
    local_root: [u8; 32],
    permission: &crate::service::native_v6_ha_install::NativeIngressSelectionPermit,
) -> Result<Option<NativeV6IngressRead>, String> {
    let failure =
        NativeV6FailureObservation::start("fresh_ingress_permission", deadline.instant());
    let result: Result<Option<NativeV6IngressRead>, String> = (|| {
        permission.check_initial_read(deadline, local_root)?;
        failure.step("fresh_ingress_runtime");
        let native = self
            .native_v6
            .as_ref()
            .filter(|native| native.enabled())
            .ok_or("native HA was not explicitly enabled")?;
        let node = self.node.as_ref().ok_or("HA process is shut down")?;
        let storage = native
            .storage
            .get()
            .ok_or("native ciphertext store absent")?;
        failure.step("fresh_ingress_storage_operation");
        let operation = storage
            .begin_native_operation()
            .map_err(|e| e.to_string())?;
        failure.step("fresh_ingress_read_index");
        let selected = self
            .runtime
            .block_on(node.native_v6_committed_root_read(deadline.instant()))
            .map_err(|e| e.to_string())?;
        let Some(selected) = selected else {
            return Ok(None);
        };
        failure.step("fresh_ingress_enrollment");
        native.validate_enrollment(&self.codec, selected.enrollment())?;
        let selected = if selected.root().root_digest() == local_root {
            failure.step("fresh_ingress_same_root_closure");
            match read_native_v6_fresh_ingress_closure(
                node,
                self.runtime.handle(),
                &self.peers,
                Arc::clone(storage),
                selected,
            )
            .map_err(|e| e.to_string())?
            {
                NativeV6IngressClosureRead::Complete(read) => read,
                NativeV6IngressClosureRead::NeedsOriginalRepair(read) => {
                    // This is the first original repair, never a no-effects
                    // continuation. No supersession token can escape it.
                    failure.step("fresh_ingress_original_repair");
                    permission.refuse_reselection();
                    recover_native_v6_committed_closure(
                        node,
                        self.runtime.handle(),
                        &native.transport,
                        &self.peers,
                        storage,
                        read,
                    )
                    .map_err(|e| e.to_string())?
                    .into_parts()
                    .0
                }
                NativeV6IngressClosureRead::Superseded(selected) => {
                    return Ok(Some(NativeV6IngressRead::Superseded(
                        NativeV6IngressSuperseded {
                            _operation: operation,
                            instance: Arc::clone(&native.identity),
                            selected,
                            deadline,
                            request_attempt: permission.attempt_identity(),
                        },
                    )));
                }
            }
        } else {
            // The initial actual selection already differs: retain the one
            // original full catch-up, with no changed-root reselection token.
            failure.step("fresh_ingress_changed_root_recover");
            permission.refuse_reselection();
            read_or_recover_native_v6_committed_closure(
                node,
                self.runtime.handle(),
                &native.transport,
                &self.peers,
                storage,
                selected,
            )
            .map_err(|e| e.to_string())?
        };
        let read = CommittedNativeV6Read {
            _operation: operation,
            instance: Arc::clone(&native.identity),
            selected,
            deadline,
        };
        failure.step("fresh_ingress_final_witness");
        self.verify_native_v6_committed_read(&read)?;
        Ok(Some(NativeV6IngressRead::Ready(read)))
    })();
    if let Err(reason) = &result {
        failure.refused("fresh_ingress_read_refused", reason);
        permission.refuse_reselection();
    } else {
        failure.complete();
    }
    result
}

fn read_native_v6_fresh_ingress_closure_inner(
    raft: &ProcessRaftNode,
    runtime: &Handle,
    routes: &BTreeMap<u64, NodeId>,
    storage: Arc<LocalV6BlobStage>,
    selected: NativeV6CommittedRootRead,
    #[cfg(test)] mut observer: Option<&mut dyn FnMut(usize) -> Result<(), HaError>>,
) -> Result<NativeV6IngressClosureRead, HaError> {
    require_blocking_worker()?;
    check_deadline(
        selected
            .operation_deadline()
            .min(selected.read_index_deadline()),
    )?;
    let pins = selected.enrollment().pins();
    if !pins.contains_key(&raft.id())
        || routes.keys().copied().collect::<BTreeSet<_>>() != pins.keys().copied().collect()
        || routes.values().collect::<BTreeSet<_>>().len() != routes.len()
    {
        return Err(HaError::InvalidMembership);
    }
    let operation = storage
        .begin_native_operation()
        .map_err(|_| HaError::Transport)?;
    let refusal = Cell::new(Refusal::None);
    #[cfg(test)]
    let mut gates = 0;
    let mut gate = || {
        if refusal.get() == Refusal::Other {
            return Err(LocalV6BlobError::CorruptOrChanged);
        }
        #[cfg(test)]
        {
            gates += 1;
            if let Some(observer) = observer.as_mut()
                && observer(gates).is_err()
            {
                refusal.set(Refusal::Other);
                return Err(LocalV6BlobError::CorruptOrChanged);
            }
        }
        if check_deadline(
            selected
                .operation_deadline()
                .min(selected.read_index_deadline()),
        )
        .is_err()
        {
            refusal.set(Refusal::Other);
            return Err(LocalV6BlobError::CorruptOrChanged);
        }
        let verified = runtime.block_on(raft.verify_native_v6_committed_root_read(&selected));
        // Verification itself may wait until its capped deadline and report
        // Consensus. Such a timeout is not an application-progress refusal.
        if check_deadline(
            selected
                .operation_deadline()
                .min(selected.read_index_deadline()),
        )
        .is_err()
        {
            refusal.set(Refusal::Other);
            return Err(LocalV6BlobError::CorruptOrChanged);
        }
        match verified {
            Ok(()) => Ok(()),
            Err(heptabao_raft_runtime::RemoteRaftError::Consensus(_)) => {
                // This is explicitly a historical ciphertext DATA pass, not a
                // current-read gate. Finish physical validation independently
                // so a post-read witness refusal cannot mask an earlier EIO,
                // Interrupted, short EOF, parse or digest failure.
                refusal.set(Refusal::Witness);
                Ok(())
            }
            Err(_) => {
                refusal.set(Refusal::Other);
                Err(LocalV6BlobError::CorruptOrChanged)
            }
        }
    };
    // Unlike reopen_root_closure's current-read contract, the archive primitive
    // explicitly returns historical DATA only. All strict readers remain
    // unchanged. No live handle is returned from this pass alone.
    let reopened = storage.reopen_root_closure_archive(selected.root(), &mut gate);
    let historical_data = match reopened {
        Ok((_manifest, references)) => {
            wire::exact_manifest(&references, &selected.root().intent())?;
            gate().map_err(|_| unknown())?;
            HistoricalClosureData {
                _root: selected.root().root_digest(),
                _objects: references.len(),
            }
        }
        Err(_) if refusal.get() != Refusal::Other => {
            // The original exact-root repair is still available, but it can
            // never return this no-effects supersession token after entry.
            return Ok(NativeV6IngressClosureRead::NeedsOriginalRepair(selected));
        }
        Err(_) => return Err(unknown()),
    };
    let witness_only = refusal.get() == Refusal::Witness;
    // An I/O/timeout error here is terminal. Do not reclassify it by subsequently
    // checking whether the old witness also happened to become invalid.
    let fresh = runtime
        .block_on(raft.native_v6_fresh_ingress_selection_read(&selected))
        .map_err(|_| unknown())?;
    let advanced = fresh.application_generation() > selected.application_generation();
    if !advanced {
        if witness_only || fresh.root() != selected.root() {
            return Err(unknown());
        }
        return Ok(NativeV6IngressClosureRead::Complete(fresh));
    }
    check_deadline(
        selected
            .operation_deadline()
            .min(selected.read_index_deadline()),
    )?;
    // A successful NEW quorum read must come first. Only then confirm that
    // the original opaque witness is actually refused; a network failure is
    // never replaced by an unrelated old-witness observation.
    match runtime.block_on(raft.verify_native_v6_committed_root_read(&selected)) {
        Err(heptabao_raft_runtime::RemoteRaftError::Consensus(_)) => {}
        Ok(()) | Err(_) => return Err(unknown()),
    }
    check_deadline(
        selected
            .operation_deadline()
            .min(selected.read_index_deadline()),
    )?;
    Ok(NativeV6IngressClosureRead::Superseded(
        NativeV6IngressSupersededRead {
            previous: Box::new(selected),
            fresh,
            storage,
            _operation: operation,
            _historical_data: historical_data,
        },
    ))
}

pub(super) fn validate_reference(reference: &RecordObjectRef) -> Result<(), HaError> {
    if reference.id == [0; 32]
        || reference.kind != RecordObjectKind::NativeV6CiphertextChunk
        || reference.record_count != 0
        || reference.payload_bytes != u64::from(reference.encoded_bytes)
        || !(25..=MAX_CIPHERTEXT as u32).contains(&reference.encoded_bytes)
    {
        return Err(HaError::InvalidFrame);
    }
    Ok(())
}

pub(super) fn exact_manifest(
    references: &[RecordObjectRef],
    intent: &NativeV6CommitIntent,
) -> Result<(), HaError> {
    if references.is_empty()
        || references.len() > MAX_OBJECTS
        || references.len() as u64 != intent.object_count
    {
        return Err(HaError::InvalidFrame);
    }
    let mut hash = Context::new(&SHA256);
    hash.update(b"heptabao.v6.local-ciphertext-closure.v1\0");
    hash.update(&(references.len() as u64).to_be_bytes());
    let mut previous = None;
    let mut total = 0u64;
    for reference in references {
        validate_reference(reference)?;
        if previous.is_some_and(|id| id >= reference.id) {
            return Err(HaError::InvalidFrame);
        }
        previous = Some(reference.id);
        total = total
            .checked_add(reference.payload_bytes)
            .ok_or(HaError::InvalidFrame)?;
        hash.update(&reference.id);
        hash.update(&reference.payload_bytes.to_be_bytes());
    }
    if hash.finish().as_ref() != intent.closure_manifest_sha256.as_slice()
        || total != intent.ciphertext_bytes
    {
        return Err(HaError::InvalidFrame);
    }
    Ok(())
}

